INSERT INTO feature VALUES('presented-types','rules','Presented types',NULL,'implemented','notable',NULL,'A data block declares constructors, operations and rules, and conversion at the type compares normal forms under its rules. A path by reflexivity reads a call of a recursive operation by the rules of the operation, in the checker and in the kernel alike. A rule removes a constructor, or it keeps the count and puts the root of its left side above each constructor of its right side, in an order with no cycle that the kernel computes. An indexed family that binds no parameter and states closed indices presents rules over its constructors, and each rule keeps the index of each term (#8338). In any other indexed family such a rule is declined where it is written (`OutOfFragment.Indexed`, #1314), while a rule over one of its operations is kept.','surface-lowering core-checker kernel-core kernel-term','corpus/model/data/arrows.gandr corpus/model/data/ruled-operation-path.gandr corpus/model/identity/loop-space.gandr corpus/model/desc/family-with-rules.gandr corpus/pathological/desc/family-with-rules.gandr corpus/pathological/data/indexed-family-rule-declined.gandr corpus/model/desc/rule-keeps-count.gandr corpus/pathological/desc/rule-keeps-count.gandr','corpus/model/data/arrows.gandr',NULL);
